package net.civeira.phylax.features.access.userroleassignment.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.userroleassignment.domain.UserRoleAssignment;
import net.civeira.phylax.features.access.userroleassignment.domain.event.UserRoleAssignmentEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class UserRoleAssignmentEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<UserRoleAssignmentEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final UserRoleAssignment entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
